"""Small dependency-free Admin interface over the authenticated API."""

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["admin-ui"])

_PAGE = r"""<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AI My Time — Admin</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#16202a;background:#f6f8fb}body{margin:0}main{max-width:1180px;margin:auto;padding:28px}h1{margin:0 0 6px}h2{font-size:18px;margin:0 0 8px}h3{font-size:16px;margin:16px 0 8px}.muted{color:#64748b}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}.card,section,details{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:16px;margin-top:18px}.card{margin:0}.metric{font-size:28px;font-weight:700}.metric-link{display:block;text-decoration:none;color:inherit}.metric-link:hover{background:#f0fdfa}summary{cursor:pointer;font-weight:700;font-size:18px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;border-bottom:1px solid #e2e8f0;padding:9px;vertical-align:top}button{background:#0f766e;color:#fff;border:0;border-radius:6px;padding:8px 11px;cursor:pointer;margin:3px}button.secondary{background:#475569}button.danger{background:#b91c1c}input,textarea,select{padding:9px;border:1px solid #cbd5e1;border-radius:6px;margin:0;max-width:100%;box-sizing:border-box}textarea{display:block;width:100%;min-height:96px}.hidden{display:none}pre{white-space:pre-wrap;overflow:auto;background:#f8fafc;padding:10px;border-radius:6px;max-height:320px}a{color:#0f766e;cursor:pointer}.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.pager{margin-top:10px}.person-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px}.field{background:#f8fafc;padding:9px;border-radius:6px}.field b{display:block;font-size:12px;color:#64748b;margin-bottom:3px}.pill{display:inline-block;border-radius:999px;background:#e2e8f0;padding:2px 8px;font-size:12px}.priority{color:#991b1b;font-weight:700}.split{display:grid;grid-template-columns:1fr 1fr;gap:16px}.work-note{margin:4px 0 0}.audience-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;max-width:100%}.audience-field{display:grid;gap:6px;min-width:0}.audience-field.full{grid-column:1/-1}.audience-field label,.audience-field legend{font-size:13px;font-weight:700;color:#334155}.audience-field select,.audience-field input{width:100%;min-width:0}.audience-fieldset{border:1px solid #cbd5e1;border-radius:8px;padding:12px;margin:0;min-width:0}.option-list{display:flex;flex-wrap:wrap;gap:8px;padding:10px;border:1px solid #cbd5e1;border-radius:8px;min-height:42px;background:#fff}.option-list .choice{display:flex;align-items:center;gap:6px;padding:6px 9px;border:1px solid #cbd5e1;border-radius:999px;background:#f8fafc;font-size:13px;font-weight:400;color:#16202a;cursor:pointer}.option-list .choice:has(input:checked){background:#d1fae5;border-color:#0f766e}.option-list input{width:auto;margin:0}.range-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.system-audience{background:#f0fdfa}.system-badge{display:inline-block;margin-left:8px;padding:2px 7px;border-radius:999px;background:#0f766e;color:#fff;font-size:11px;font-weight:700;white-space:nowrap}.system-note{font-size:12px;color:#0f766e}.work-note{margin:4px 0 0}@media(max-width:760px){main{padding:14px}.split,.audience-form,.range-fields{grid-template-columns:1fr}table{font-size:12px}}
</style></head><body><main>
<header><h1>Рабочий кабинет OWNER</h1><div class="muted">Сначала новые обращения и задачи, затем люди и история.</div><div id="identity" class="muted">Вход требуется</div></header>
<section id="login"><h2>Вход</h2><form id="login-form"><input name="email" type="email" placeholder="Электронная почта" required><input name="password" type="password" placeholder="Пароль" required><button>Войти</button></form><button class="secondary" id="reset-button">Восстановить пароль</button><div id="login-error" class="muted"></div></section>
<div id="app" class="hidden"><section><h2>Сегодня в работе</h2><p class="muted work-note">Новые — ждут первого ответа. «В работе» — уже взяты OWNER. Закрытые записи находятся в истории.</p><div class="grid" id="dashboard"></div></section>
<details open id="work-queue"><summary>Очередь работы</summary><div class="split"><div><h3>Консультации</h3><p class="muted">Заявки, где нужен ответ или ведётся работа.</p><div class="row"><button class="secondary" data-list="consultations" data-history="false">Активные</button><button class="secondary" data-list="consultations" data-history="true">История</button></div><div id="consultations"></div></div><div><h3>Отдельные задачи внимания</h3><p class="muted">Задачи из консультаций меняются вместе с консультацией и не требуют двойной отметки.</p><div class="row"><button class="secondary" data-list="attention" data-history="false">Активные</button><button class="secondary" data-list="attention" data-history="true">История</button></div><div id="attention"></div></div></div></details>
<details open><summary>Люди</summary><p class="muted">Откройте карточку, чтобы увидеть источник, сегмент бизнеса, пройденные шаги и связь.</p><div class="row"><input id="search" placeholder="Имя или @username"><button class="secondary" id="search-button">Найти</button></div><div id="people"></div></details>
<details open><summary>Аудитории</summary><p class="muted">Динамические группы: состав пересчитывается из текущих данных. В этом разделе нет рассылок и отправки сообщений.</p><h3>Создать аудиторию</h3><form id="audience-form" class="audience-form"><div class="audience-field full"><label for="audience-title">Название аудитории</label><input id="audience-title" required></div><div class="audience-field"><label for="content-subscription">Подписка на полезные материалы</label><select id="content-subscription"><option value="">Любое состояние</option><option value="subscribed">Получает полезные материалы</option><option value="unsubscribed">Не получает полезные материалы</option></select></div><div class="audience-field"><label for="commercial-result">Коммерческий результат</label><select id="commercial-result"><option value="">Любой результат</option><option value="purchased">Купил</option><option value="not_purchased">Не купил</option><option value="decision_pending">Решение пока не принято</option></select></div><div class="audience-field"><label for="source-codes">Источники</label><select id="source-codes" multiple></select><span class="muted">Можно выбрать несколько</span></div><div class="audience-field"><label for="campaign-codes">Кампании</label><select id="campaign-codes" multiple></select><span class="muted">Можно выбрать несколько</span></div><div class="audience-field"><label for="business-segments">Сегменты бизнеса</label><select id="business-segments" multiple></select><span class="muted">Можно выбрать несколько</span></div><div class="audience-field"><label for="diagnostic-stages">Стадии диагностики</label><select id="diagnostic-stages" multiple></select><span class="muted">Можно выбрать несколько</span></div><div class="audience-field"><label for="consultation-statuses">Статусы консультации</label><select id="consultation-statuses" multiple></select><span class="muted">Можно выбрать несколько</span></div><fieldset class="audience-field audience-fieldset"><legend>Первое появление</legend><div class="range-fields"><div class="audience-field"><label for="first-seen-from">С</label><input id="first-seen-from" type="datetime-local"></div><div class="audience-field"><label for="first-seen-to">По</label><input id="first-seen-to" type="datetime-local"></div></div></fieldset><div class="audience-field full"><button>Сохранить аудиторию</button></div></form><div id="audiences"></div><section id="audience-panel" class="hidden"><div class="row"><h3 id="audience-panel-title"></h3><button class="secondary" id="close-audience">Закрыть</button></div><div id="audience-members"></div></section></details>
<section id="person-panel" class="hidden"><div class="row"><h2>Карточка человека</h2><button class="secondary" id="close-person">Закрыть карточку</button></div><div id="person"></div></section>
<details><summary>Учётная запись OWNER</summary><p class="muted">Измените адрес входа на ваш рабочий email. Для подтверждения нужен текущий пароль.</p><form id="email-form"><input id="owner-email" type="email" placeholder="Новый email" required><input id="owner-password" type="password" placeholder="Текущий пароль" required><button>Изменить email входа</button></form><div id="email-result" class="muted"></div></details><button class="secondary" id="logout">Выйти</button></div>
</main><script>
const $=id=>document.getElementById(id), PAGE=20, state={people:0,consultations:0,attention:0,audiences:0,consultationsHistory:false,attentionHistory:false};
const esc=v=>String(v??'—').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const human={new:'Новая',waiting_response:'Ждём ответа',scheduled:'Назначена',no_show:'Не состоялась',primary_diagnostic:'Первичное обращение',repeat_task:'Повторное обращение — новая задача',purchased:'Купил',not_purchased:'Не купил',decision_pending:'Решение пока не принято',profiling:'Заполнение профиля',diagnostic_in_progress:'Диагностика в процессе',diagnostic_ready:'Диагностика завершена',diagnostic_completed:'Диагностика завершена',consultation_requested:'Запрошена консультация',consultation_scheduled:'Назначена встреча',consultation_completed:'Консультация проведена',consultation_cancelled:'Консультация отменена',consultation_no_show:'Консультация не состоялась',subscribed:'Получает сообщения',unsubscribed:'Отписан',confirmed:'Подтверждена',revoked:'Отозвано',unknown:'Не подтверждено',allowed:'Доступен в Telegram',blocked:'Недоступен в Telegram',draft:'Черновик',queued:'В очереди',sent:'Отправлено',failed:'Не доставлено',pending:'Ожидает подтверждения',processing:'Отправляется',open:'Открыта',in_progress:'В работе',completed:'Проведена',cancelled:'Отменена',resolved:'Обработано',closed:'Закрыта',normal:'Обычный',high:'Высокий',urgent:'Срочный',recorded:'Зафиксировано',profile_answered:'Получен ответ профиля',diagnostic_started:'Начата диагностика',diagnostic_completed:'Диагностика завершена',content_subscribed:'Подписка включена',content_unsubscribed:'Подписка отключена',telegram_delivery:'Доставка в Telegram',message:'Сообщение',consultation_request:'Заявка на консультацию'};
function label(v){return human[v]||String(v??'—').replaceAll('_',' ')} function source(v){return v==='conference_2026'?'Конференция 2026':(v?label(v):'—')} function date(v){return v?new Date(v).toLocaleString('ru-RU',{timeZone:'Europe/Moscow'}):'—'} function answer(v){return v&&typeof v==='object'&&'value'in v?String(v.value):typeof v==='string'?v:'—'}
function personContact(p){const name=esc(p.display_name||'Без имени');const username=p.telegram_username?.replace(/^@/,'');if(username)return '<a href="https://t.me/'+encodeURIComponent(username)+'" target="_blank" rel="noopener">'+name+' · @'+esc(username)+'</a>';return '<a data-person="'+p.user_id+'">'+name+' · Открыть контакт</a>'}
async function api(path,opts={}){const r=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});if(!r.ok)throw new Error((await r.json().catch(()=>({detail:r.statusText}))).detail||r.statusText);return r.status===204?null:r.json()}
function table(rows,cols){if(!rows.length)return '<p class="muted">Нет данных</p>';return '<table><thead><tr>'+cols.map(c=>'<th>'+c[0]+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr class="'+(r.is_system?'system-audience':'')+'">'+cols.map(c=>'<td>'+(typeof c[1]==='function'?c[1](r):esc(r[c[1]]))+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function pager(kind,count){const disabledPrev=state[kind]===0?'disabled':'';const disabledNext=count<PAGE?'disabled':'';return '<div class="pager"><button class="secondary" data-page="'+kind+'" data-delta="-20" '+disabledPrev+'>Назад</button><button class="secondary" data-page="'+kind+'" data-delta="20" '+disabledNext+'>Далее</button></div>'}
function consultationActions(x){const id=x.consultation_request_id;if(x.status==='new')return '<button data-status-kind="consultations" data-status-id="'+id+'" data-status="waiting_response">Ждём ответа</button><button data-appointment="'+id+'">Назначить время</button>';if(x.status==='waiting_response')return '<button data-appointment="'+id+'">Назначить время</button><button class="danger" data-status-kind="consultations" data-status-id="'+id+'" data-status="cancelled">Отменена</button>';if(x.status==='scheduled')return '<button data-appointment="'+id+'">Изменить время</button><button data-owner-confirm="'+id+'">OWNER подтвердил</button><button data-status-kind="consultations" data-status-id="'+id+'" data-status="completed">Проведена</button><button class="danger" data-status-kind="consultations" data-status-id="'+id+'" data-status="cancelled">Отменена</button><button class="danger" data-status-kind="consultations" data-status-id="'+id+'" data-status="no_show">Не состоялась</button>';if(x.status==='completed')return '<button data-commercial="'+id+'" data-result="purchased">Купил</button><button data-commercial="'+id+'" data-result="not_purchased">Не купил</button><button data-commercial="'+id+'" data-result="decision_pending">Решение пока не принято</button>';return '—'}
function attentionActions(x){if(x.consultation_request_id)return '<span class="muted">Синхронизируется с консультацией</span>';if(x.status==='new')return '<button data-status-kind="attention" data-status-id="'+x.attention_item_id+'" data-status="in_progress">В работу</button>';if(x.status==='in_progress')return '<button data-status-kind="attention" data-status-id="'+x.attention_item_id+'" data-status="resolved">Обработано</button>';return '—'}
async function setStatus(kind,id,status){try{await api('/admin/'+kind+'/'+id,{method:'PATCH',body:JSON.stringify({status})});await load()}catch(err){alert('Не удалось обновить статус: '+err.message)}}
async function appointment(id){const local=prompt('Дата и время консультации (МСК): ГГГГ-ММ-ДДTЧЧ:ММ');if(!local)return;try{await api('/admin/consultations/'+id+'/appointment',{method:'POST',body:JSON.stringify({appointment_at:local+':00+03:00'})});await load()}catch(err){alert(err.message.includes('under one hour')?'Встречу менее чем через час можно назначить только с ручным подтверждением OWNER.':('Не удалось назначить: '+err.message))}}
async function ownerConfirm(id){try{await api('/admin/consultations/'+id+'/owner-confirm',{method:'POST'});await load()}catch(err){alert('Не удалось подтвердить: '+err.message)}}
async function commercial(id,result){try{await api('/admin/consultations/'+id+'/commercial-result',{method:'PATCH',body:JSON.stringify({commercial_result:result})});await load()}catch(err){alert('Не удалось сохранить результат: '+err.message)}}
function bind(){document.querySelectorAll('[data-person]').forEach(x=>x.onclick=()=>person(x.dataset.person));document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>{state[x.dataset.page]=Math.max(0,state[x.dataset.page]+Number(x.dataset.delta));loadLists()});document.querySelectorAll('[data-list]').forEach(x=>x.onclick=()=>{const key=x.dataset.list;state[key+'History']=x.dataset.history==='true';state[key]=0;loadLists()});document.querySelectorAll('[data-status-kind]').forEach(x=>x.onclick=()=>setStatus(x.dataset.statusKind,x.dataset.statusId,x.dataset.status));document.querySelectorAll('[data-appointment]').forEach(x=>x.onclick=()=>appointment(x.dataset.appointment));document.querySelectorAll('[data-owner-confirm]').forEach(x=>x.onclick=()=>ownerConfirm(x.dataset.ownerConfirm));document.querySelectorAll('[data-commercial]').forEach(x=>x.onclick=()=>commercial(x.dataset.commercial,x.dataset.result));document.querySelectorAll('[data-audience-members]').forEach(x=>x.onclick=()=>audienceMembers(x.dataset.audienceMembers,x.dataset.audienceTitle));document.querySelectorAll('[data-audience-edit]').forEach(x=>x.onclick=()=>editAudience(x.dataset.audienceEdit));document.querySelectorAll('[data-audience-delete]').forEach(x=>x.onclick=()=>deleteAudience(x.dataset.audienceDelete));}
async function loadLists(){const q=$('search').value?'&search='+encodeURIComponent($('search').value):'';const [p,c,a,u]=await Promise.all([api('/admin/people?limit='+PAGE+'&offset='+state.people+q),api('/admin/consultations?history='+state.consultationsHistory+'&limit='+PAGE+'&offset='+state.consultations),api('/admin/attention?standalone=true&history='+state.attentionHistory+'&limit='+PAGE+'&offset='+state.attention),api('/admin/audiences?limit='+PAGE+'&offset='+state.audiences)]);$('people').innerHTML=table(p.items,[['Человек',x=>'<a data-person="'+x.user_id+'">'+esc(x.display_name||'Без имени')+'</a>'+(x.telegram_username?'<br><span class="muted">@'+esc(x.telegram_username.replace(/^@/,''))+'</span>':'')],['Откуда',x=>source(x.source)],['Сегмент бизнеса',x=>esc(x.business_segment||'Не указан')],['Прошёл',x=>label(x.diagnostic_status)],['Работа',x=>x.consultation_status?label(x.consultation_status):(x.attention_count?'Есть задача внимания':'—')]])+pager('people',p.items.length);$('consultations').innerHTML=table(c.items,[['Человек',x=>personContact(x.person)],['Обращение',x=>'<b>'+label(x.origin_type)+'</b><br>'+esc(x.repeat_task_text||x.diagnostic_summary||'—')],['Встреча',x=>date(x.appointment_at)],['Подтверждение',x=>'<span class="pill">'+label(x.confirmation_state)+'</span>'],['Статус',x=>'<span class="pill">'+label(x.status)+'</span>'+(x.commercial_result?'<br>'+label(x.commercial_result):'')],['Действие',consultationActions]])+pager('consultations',c.items.length);$('attention').innerHTML=table(a.items,[['Человек',x=>personContact(x.person)],['Что требует внимания',x=>esc(x.reason)],['Приоритет',x=>'<span class="'+(x.priority==='urgent'?'priority':'')+'">'+label(x.priority)+'</span>'],['Статус',x=>'<span class="pill">'+label(x.status)+'</span>'],['Действие',attentionActions]])+pager('attention',a.items.length);$('audiences').innerHTML=table(u.items,[['Аудитория','title'],['Участников сейчас','current_count'],['Условия',x=>x.is_system?'Системная аудитория':'Настраиваемые'],['Действие',x=>'<button class="secondary" data-audience-members="'+x.audience_id+'" data-audience-title="'+esc(x.title)+'">Открыть список</button>'+(x.is_system?'':'<button class="secondary" data-audience-edit="'+x.audience_id+'">Редактировать</button><button class="danger" data-audience-delete="'+x.audience_id+'">Удалить</button>')]])+pager('audiences',u.items.length);bind()}
async function load(){const d=await api('/admin/dashboard');const cards=[['Новые консультации',d.new_consultations,'work-queue'],['Консультации в работе',d.consultations_in_progress,'work-queue'],['Новые задачи внимания',d.new_attention_items,'work-queue'],['Задачи в работе',d.attention_in_progress,'work-queue'],['Новые люди за 7 дней',d.new_people,'']];$('dashboard').innerHTML=cards.map(x=>'<a class="card metric-link" '+(x[2]?'href="#'+x[2]+'"':'')+'><div class="muted">'+x[0]+'</div><div class="metric">'+x[1]+'</div></a>').join('');await loadLists()}
async function person(id){const [data,trace]=await Promise.all([api('/admin/people/'+id),api('/admin/logs/people/'+id)]),p=data.person,username=p.telegram_username?.replace(/^@/,'');const contact=username?'<a href="https://t.me/'+encodeURIComponent(username)+'" target="_blank" rel="noopener">Написать в Telegram · @'+esc(username)+'</a>':'Связь через бота';const diagnostics=data.diagnostics.map(x=>'<li><span class="pill">'+label(x.status)+'</span> '+date(x.completed_at||x.created_at)+(x.summary?'<br>'+esc(x.summary):'')+'</li>').join('')||'<li>Диагностика ещё не начата</li>';const consultations=data.consultations.map(x=>'<li><span class="pill">'+label(x.status)+'</span> '+date(x.created_at)+'</li>').join('')||'<li>Заявок на консультацию нет</li>';const latest=trace.items.slice(0,5).map(x=>'<li>'+date(x.occurred_at)+' · '+label(x.event_type)+' · '+label(x.status)+'</li>').join('')||'<li>Нет значимых событий</li>';$('person-panel').classList.remove('hidden');$('person').innerHTML='<div class="row"><h2>'+esc(p.display_name||'Человек без имени')+'</h2><span class="pill">'+(username?'@'+esc(username):'Telegram через бота')+'</span></div><p>'+contact+'</p><div class="person-grid"><div class="field"><b>Откуда пришёл</b>'+source(p.source)+'</div><div class="field"><b>Кампания</b>'+source(p.conference_code)+'</div><div class="field"><b>Сегмент бизнеса</b>'+esc(p.business_segment||answer(data.profile_answers.business_type))+'</div><div class="field"><b>Сейчас проходит</b>'+label(p.lifecycle_stage)+'</div><div class="field"><b>Диагностика</b>'+label(p.diagnostic_status)+'</div><div class="field"><b>Консультация</b>'+label(p.consultation_status)+'</div><div class="field"><b>Полезные материалы</b>'+label(p.content_subscription_status)+'</div></div>'+(username?'':'<h3>Написать через бота</h3><p class="muted">Сообщение будет отправлено только после вашего подтверждения.</p><form id="telegram-message-form"><textarea id="telegram-message-text" placeholder="Сообщение человеку" required></textarea><button>Поставить сообщение в очередь</button><div id="telegram-message-result" class="muted"></div></form>')+'<div class="split"><div><h3>Что человек прошёл</h3><ul>'+diagnostics+'</ul></div><div><h3>Консультации</h3><ul>'+consultations+'</ul></div></div><h3>Последние значимые события</h3><ul>'+latest+'</ul>'+'<details><summary>Технические данные</summary><p class="muted">Для разбора с разработчиком.</p><pre>'+esc(JSON.stringify(data,null,2))+'</pre></details>';const form=$('telegram-message-form');if(form)form.onsubmit=async e=>{e.preventDefault();if(!confirm('Отправить это сообщение через бота?'))return;try{await api('/admin/people/'+id+'/telegram-message',{method:'POST',body:JSON.stringify({text:$('telegram-message-text').value})});$('telegram-message-result').textContent='Сообщение поставлено в очередь.'}catch(err){$('telegram-message-result').textContent='Не удалось поставить сообщение: '+err.message}};$('person-panel').scrollIntoView({behavior:'smooth',block:'start'})}
const selected=id=>Array.from($(id).querySelectorAll('input:checked')).map(x=>x.value);const iso=id=>$(id).value?new Date($(id).value).toISOString():undefined;
const displayNames={conference_2026:'Конференция 2026',prepared:'Ожидает диагностики',diagnostic_active:'Диагностика в процессе',diagnostic_completed:'Диагностика завершена',new:'Новая заявка',waiting_response:'Ожидаем ответа',scheduled:'Встреча назначена',completed:'Консультация проведена',cancelled:'Консультация отменена',no_show:'Не состоялась',vk:'ВКонтакте',max:'MAX',telegram:'Telegram',site:'Сайт',website:'Сайт',unknown:'Источник не указан'};
function displayLabel(value,kind){if(displayNames[value])return displayNames[value];const text=String(value).replaceAll('_',' ').replaceAll('-',' ').replace(/\b\w/g,x=>x.toUpperCase());return kind==='campaign'?'Кампания «'+text+'»':text}
function setOptions(id,values,kind){const field=$(id);field.outerHTML='<div id="'+id+'" class="option-list" aria-label="'+esc(kind)+'">'+(values.length?values.map(value=>'<label class="choice"><input type="checkbox" value="'+esc(value)+'"><span>'+esc(displayLabel(value,kind))+'</span></label>').join(''):'<span class="muted">Пока нет вариантов</span>')+'</div>'}
function selectValues(id,values){const wanted=new Set(values||[]);$(id).querySelectorAll('input').forEach(input=>input.checked=wanted.has(input.value))}
async function loadAudienceOptions(){const options=await api('/admin/audience-options');setOptions('source-codes',options.source_codes,'источники');setOptions('campaign-codes',options.campaign_codes,'кампании');setOptions('business-segments',options.business_segments,'сегменты бизнеса');setOptions('diagnostic-stages',options.diagnostic_stages,'стадии диагностики');setOptions('consultation-statuses',options.consultation_statuses,'статусы консультации')}
function audiencePayload(){const c={content_subscription_status:$('content-subscription').value||undefined,source_codes:selected('source-codes'),campaign_codes:selected('campaign-codes'),business_segments:selected('business-segments'),diagnostic_stages:selected('diagnostic-stages'),consultation_statuses:selected('consultation-statuses'),commercial_results:$('commercial-result').value?[$('commercial-result').value]:undefined,first_seen_from:iso('first-seen-from'),first_seen_to:iso('first-seen-to')};Object.keys(c).forEach(k=>{if(c[k]===undefined||Array.isArray(c[k])&&!c[k].length)delete c[k]});return {title:$('audience-title').value,conditions:c}}
async function audienceMembers(id,title){const x=await api('/admin/audiences/'+id+'/members?limit=100');$('audience-panel-title').textContent=title+' · '+x.total_count;$('audience-members').innerHTML=table(x.items,[['Человек',z=>'<a data-person="'+z.user_id+'">'+esc(z.display_name||'Без имени')+'</a>'],['Telegram',z=>esc(z.telegram_username?'@'+z.telegram_username.replace(/^@/,''):'—')],['Первое появление',z=>date(z.created_at)]]);$('audience-panel').classList.remove('hidden');bind()}
async function editAudience(id){const x=await api('/admin/audiences/'+id);$('audience-title').value=x.title;const c=x.conditions;$('content-subscription').value=c.content_subscription_status||'';selectValues('source-codes',c.source_codes);selectValues('campaign-codes',c.campaign_codes);selectValues('business-segments',c.business_segments);selectValues('diagnostic-stages',c.diagnostic_stages);selectValues('consultation-statuses',c.consultation_statuses);$('commercial-result').value=(c.commercial_results||[])[0]||'';$('first-seen-from').value=c.first_seen_from?c.first_seen_from.slice(0,16):'';$('first-seen-to').value=c.first_seen_to?c.first_seen_to.slice(0,16):'';$('audience-form').dataset.edit=id;$('audience-form').scrollIntoView({behavior:'smooth',block:'center'})}
async function deleteAudience(id){if(!confirm('Удалить эту аудиторию?'))return;try{await api('/admin/audiences/'+id,{method:'DELETE'});await loadLists()}catch(err){alert('Не удалось удалить: '+err.message)}}
$('audience-form').onsubmit=async e=>{e.preventDefault();try{const id=e.target.dataset.edit;await api('/admin/audiences'+(id?'/'+id:''),{method:id?'PATCH':'POST',body:JSON.stringify(audiencePayload())});e.target.reset();delete e.target.dataset.edit;await loadLists()}catch(err){alert('Не удалось сохранить аудиторию: '+err.message)}};$('close-audience').onclick=()=>$('audience-panel').classList.add('hidden');$('search-button').onclick=()=>{state.people=0;loadLists()};$('close-person').onclick=()=>{$('person-panel').classList.add('hidden');$('person').innerHTML=''};$('logout').onclick=async()=>{await api('/admin/auth/logout',{method:'POST',headers:{Origin:location.origin}});location.reload()};$('reset-button').onclick=()=>{$('login-error').textContent='Восстановление пароля пока недоступно: для безопасной отправки ссылки нужен настроенный почтовый канал.'};
async function ready(){try{const me=await api('/admin/auth/me');$('identity').textContent=me.email+' · Владелец';$('owner-email').value=me.email;$('login').classList.add('hidden');$('app').classList.remove('hidden');await loadAudienceOptions();await load();return true}catch{return false}}$('login-form').onsubmit=async e=>{e.preventDefault();$('login-error').textContent='';try{const f=new FormData(e.target);await api('/admin/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});if(!await ready())throw new Error('Сессия не установлена. Обновите страницу и попробуйте ещё раз.');}catch(err){$('login-error').textContent='Не удалось войти: '+err.message}};$('email-form').onsubmit=async e=>{e.preventDefault();try{const me=await api('/admin/auth/me/email',{method:'PATCH',body:JSON.stringify({email:$('owner-email').value,password:$('owner-password').value})});$('identity').textContent=me.email+' · Владелец';$('owner-password').value='';$('email-result').textContent='Адрес входа обновлён.'}catch(err){$('email-result').textContent='Не удалось изменить адрес: '+err.message}};ready();
</script></body></html>"""


